SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID('dbo.GenerationProviders') IS NULL CREATE TABLE dbo.GenerationProviders(GenerationProviderId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,WorkspaceId UNIQUEIDENTIFIER NOT NULL,ProviderKey NVARCHAR(80) NOT NULL,DisplayName NVARCHAR(160) NOT NULL,Capability NVARCHAR(40) NOT NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'ACTIVE',ApiMode NVARCHAR(30) NOT NULL DEFAULT 'API',DefaultModel NVARCHAR(120) NULL,SupportsReferences BIT NOT NULL DEFAULT 0,SupportsBatch BIT NOT NULL DEFAULT 0,SupportsWebhook BIT NOT NULL DEFAULT 0,PriorityOrder INT NOT NULL DEFAULT 100,ConfigJson NVARCHAR(MAX) NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_GenerationProviders_Workspaces FOREIGN KEY(WorkspaceId) REFERENCES dbo.Workspaces(WorkspaceId));
IF OBJECT_ID('dbo.GenerationJobs') IS NULL CREATE TABLE dbo.GenerationJobs(GenerationJobId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,WorkspaceId UNIQUEIDENTIFIER NOT NULL,ContentProjectId UNIQUEIDENTIFIER NOT NULL,SceneId UNIQUEIDENTIFIER NULL,ScenePackageVersionId UNIQUEIDENTIFIER NULL,CharacterBibleVersionId UNIQUEIDENTIFIER NULL,Capability NVARCHAR(40) NOT NULL,ProviderKey NVARCHAR(80) NOT NULL,Model NVARCHAR(120) NULL,PromptVersion INT NOT NULL DEFAULT 1,PromptText NVARCHAR(MAX) NULL,NegativePrompt NVARCHAR(MAX) NULL,ReferenceJson NVARCHAR(MAX) NULL,SettingsJson NVARCHAR(MAX) NULL,Status NVARCHAR(30) NOT NULL DEFAULT 'QUEUED',ApprovalStatus NVARCHAR(30) NOT NULL DEFAULT 'PENDING',Priority INT NOT NULL DEFAULT 50,AttemptNumber INT NOT NULL DEFAULT 1,MaxAttempts INT NOT NULL DEFAULT 3,FallbackProviderKey NVARCHAR(80) NULL,ProgressPercent DECIMAL(5,2) NOT NULL DEFAULT 0,ExternalJobId NVARCHAR(250) NULL,EstimatedCost DECIMAL(18,4) NULL,ActualCost DECIMAL(18,4) NULL,Currency NVARCHAR(10) NOT NULL DEFAULT 'USD',CreditUnits DECIMAL(18,4) NULL,DurationSeconds DECIMAL(10,2) NULL,Resolution NVARCHAR(40) NULL,LastError NVARCHAR(MAX) NULL,QueuedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),StartedAt DATETIME2 NULL,CompletedAt DATETIME2 NULL,CreatedByUserId UNIQUEIDENTIFIER NULL,UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_GenerationJobs_Workspaces FOREIGN KEY(WorkspaceId) REFERENCES dbo.Workspaces(WorkspaceId),CONSTRAINT FK_GenerationJobs_Projects FOREIGN KEY(ContentProjectId) REFERENCES dbo.ContentProjects(ContentProjectId));
IF OBJECT_ID('dbo.GenerationJobAttempts') IS NULL CREATE TABLE dbo.GenerationJobAttempts(GenerationJobAttemptId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,GenerationJobId UNIQUEIDENTIFIER NOT NULL,AttemptNumber INT NOT NULL,ProviderKey NVARCHAR(80) NOT NULL,Model NVARCHAR(120) NULL,Status NVARCHAR(30) NOT NULL,ExternalJobId NVARCHAR(250) NULL,Cost DECIMAL(18,4) NULL,ErrorMessage NVARCHAR(MAX) NULL,StartedAt DATETIME2 NULL,CompletedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_GenerationJobAttempts_Jobs FOREIGN KEY(GenerationJobId) REFERENCES dbo.GenerationJobs(GenerationJobId));
IF OBJECT_ID('dbo.GeneratedAssets') IS NULL CREATE TABLE dbo.GeneratedAssets(GeneratedAssetId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,WorkspaceId UNIQUEIDENTIFIER NOT NULL,ContentProjectId UNIQUEIDENTIFIER NOT NULL,SceneId UNIQUEIDENTIFIER NULL,GenerationJobId UNIQUEIDENTIFIER NULL,AssetType NVARCHAR(40) NOT NULL,AssetRole NVARCHAR(80) NULL,StorageUri NVARCHAR(1000) NOT NULL,PreviewUri NVARCHAR(1000) NULL,MimeType NVARCHAR(120) NULL,FileSizeBytes BIGINT NULL,DurationSeconds DECIMAL(10,2) NULL,Width INT NULL,Height INT NULL,VersionNumber INT NOT NULL DEFAULT 1,ApprovalStatus NVARCHAR(30) NOT NULL DEFAULT 'PENDING',IsMaster BIT NOT NULL DEFAULT 0,MetadataJson NVARCHAR(MAX) NULL,ApprovedByUserId UNIQUEIDENTIFIER NULL,ApprovedAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_GeneratedAssets_Workspaces FOREIGN KEY(WorkspaceId) REFERENCES dbo.Workspaces(WorkspaceId),CONSTRAINT FK_GeneratedAssets_Projects FOREIGN KEY(ContentProjectId) REFERENCES dbo.ContentProjects(ContentProjectId),CONSTRAINT FK_GeneratedAssets_Jobs FOREIGN KEY(GenerationJobId) REFERENCES dbo.GenerationJobs(GenerationJobId));
IF OBJECT_ID('dbo.GenerationPromptVersions') IS NULL CREATE TABLE dbo.GenerationPromptVersions(GenerationPromptVersionId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,GenerationJobId UNIQUEIDENTIFIER NOT NULL,VersionNumber INT NOT NULL,PromptText NVARCHAR(MAX) NULL,NegativePrompt NVARCHAR(MAX) NULL,SettingsJson NVARCHAR(MAX) NULL,ChangeSummary NVARCHAR(1000) NULL,CreatedByUserId UNIQUEIDENTIFIER NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_GenerationPromptVersions_Jobs FOREIGN KEY(GenerationJobId) REFERENCES dbo.GenerationJobs(GenerationJobId));
IF OBJECT_ID('dbo.GenerationApprovals') IS NULL CREATE TABLE dbo.GenerationApprovals(GenerationApprovalId UNIQUEIDENTIFIER NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,GeneratedAssetId UNIQUEIDENTIFIER NOT NULL,Decision NVARCHAR(30) NOT NULL,Comment NVARCHAR(3000) NULL,DecidedByUserId UNIQUEIDENTIFIER NULL,DecidedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_GenerationApprovals_Assets FOREIGN KEY(GeneratedAssetId) REFERENCES dbo.GeneratedAssets(GeneratedAssetId));
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_GenerationJobs_ProjectStatus') CREATE INDEX IX_GenerationJobs_ProjectStatus ON dbo.GenerationJobs(ContentProjectId,Status,Capability);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_GeneratedAssets_ProjectScene') CREATE INDEX IX_GeneratedAssets_ProjectScene ON dbo.GeneratedAssets(ContentProjectId,SceneId,AssetType,ApprovalStatus);
COMMIT;
